_FOLDER_PROGRAM = r'''
import json
from pathlib import Path

profile = Path(__PROFILE_DIR__).expanduser()
local = profile / "Mail" / "Local Folders"
result = {
    "profile_dir": str(profile),
    "profile_exists": profile.is_dir(),
    "local_folders_dir": str(local),
    "local_folders_exists": local.is_dir(),
    "folders": [],
    "errors": [],
}
if local.is_dir():
    names = set()
    for child in sorted(local.iterdir()):
        name = child.name
        if name.endswith(".msf") or name == "msgFilterRules.dat":
            continue
        if name.endswith(".sbd"):
            names.add(name[:-4])
            for nested in sorted(child.iterdir()):
                nested_name = nested.name
                if nested_name.endswith(".msf"):
                    continue
                names.add(nested_name[:-4] if nested_name.endswith(".sbd") else nested_name)
        else:
            names.add(name)
    result["folders"] = sorted(name for name in names if name)
else:
    result["errors"].append("Local Folders directory is absent: " + str(local))
print(json.dumps(result, ensure_ascii=False))
'''

_RULES_PROGRAM = r'''
import json
import re
from pathlib import Path

paths = __PATHS__
attribute = re.compile(r'([A-Za-z_][A-Za-z0-9_]*)\s*=\s*"((?:[^"\\]|\\.)*)"')

result = {"files": [], "rules": [], "errors": []}
for raw in paths:
    path = Path(str(raw)).expanduser()
    entry = {"path": str(path), "exists": path.is_file(), "rule_lines": 0, "error": None}
    if path.is_file():
        try:
            text = path.read_text(encoding="utf-8", errors="replace")
        except OSError as exc:
            entry["error"] = "%s: %s" % (type(exc).__name__, exc)
        else:
            for line in text.splitlines():
                if "name=" not in line:
                    continue
                attributes = {match.group(1): match.group(2).replace('\\"', '"') for match in attribute.finditer(line)}
                if "name" not in attributes:
                    continue
                entry["rule_lines"] += 1
                attributes["__source__"] = str(path)
                result["rules"].append(attributes)
    else:
        result["errors"].append("rule file is absent: " + str(path))
    result["files"].append(entry)
print(json.dumps(result, ensure_ascii=False))
'''


def _run_program(controller: Any, program: str, timeout: int) -> dict[str, Any]:
    if controller is None or not hasattr(controller, "run_python_script"):
        raise RuntimeError("controller.run_python_script is required")
    raw = controller.run_python_script(program, timeout=timeout)
    if not isinstance(raw, Mapping):
        raise RuntimeError("runtime returned no result mapping")
    output = str(raw.get("stdout") or raw.get("output") or "").strip()
    if int(raw.get("returncode", -1)) != 0:
        raise RuntimeError(str(raw.get("stderr") or "") or output or "runtime command failed")
    try:
        return dict(json.loads(output.splitlines()[-1]))
    except (ValueError, IndexError) as exc:
        raise RuntimeError("runtime output was not JSON: %s" % exc) from exc


class ThunderbirdFolderCalendarEvaluator(BaseEvaluator):
    """Verify a required mail folder and a required calendar event title."""

    PASS_MESSAGE = "Thunderbird folder and calendar checks passed"
    FAIL_MESSAGE = "Thunderbird folder and calendar checks failed"

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        timeout = int(params.get("timeout", DEFAULT_TIMEOUT) or DEFAULT_TIMEOUT)
        profile_dir = str(params.get("profile_dir") or DEFAULT_PROFILE_DIR)
        required_folder = str(params.get("required_folder") or "").strip()
        required_event_title = str(params.get("required_event_title") or "").strip()
        seed_folders = [str(item) for item in (params.get("expected_seed_folders") or [])]
        if not required_folder and not required_event_title:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="the task declares neither a required mail folder nor a required event title",
            )

        controller = context.get("controller")
        try:
            folders = _run_program(
                controller,
                _FOLDER_PROGRAM.replace("__PROFILE_DIR__", repr(profile_dir)),
                timeout,
            )
        except Exception as exc:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="Thunderbird mail folders could not be read: %s: %s" % (type(exc).__name__, exc),
            )

        checks: list[dict[str, Any]] = []
        observed_folders = [str(name) for name in folders.get("folders") or []]

        for name in seed_folders:
            present = name in observed_folders
            checks.append(
                {
                    "check_id": "seed_folder:%s" % name,
                    "passed": present,
                    "expected": {"folder": name, "present": True},
                    "observed": {"present": present},
                }
            )

        if required_folder:
            present = required_folder in observed_folders
            checks.append(
                {
                    "check_id": "folder:%s" % required_folder,
                    "passed": present,
                    "expected": {"folder": required_folder, "present": True},
                    "observed": {"folders": observed_folders},
                }
            )

        calendar_evidence: dict[str, Any] = {}
        if required_event_title:
            try:
                calendar_evidence = read_calendar_evidence(
                    controller,
                    {"profile_dir": profile_dir, "timeout": timeout},
                )
            except Exception as exc:
                calendar_evidence = {"error": "%s: %s" % (type(exc).__name__, exc)}
            titles = self._calendar_titles(calendar_evidence)
            present = required_event_title in titles
            checks.append(
                {
                    "check_id": "event_title:%s" % required_event_title,
                    "passed": present,
                    "expected": {"title": required_event_title, "present": True},
                    "observed": {"matching_title_present": present, "event_count": len(titles)},
                }
            )

        failed = [check["check_id"] for check in checks if not check["passed"]]
        metadata = {
            "profile_dir": folders.get("profile_dir"),
            "local_folders_dir": folders.get("local_folders_dir"),
            "folders": observed_folders,
            "folder_errors": folders.get("errors"),
            "calendar_error": calendar_evidence.get("error") or calendar_evidence.get("calendar_error"),
            "checks": checks,
            "failures": failed,
        }
        if not checks:
            return EvalResult(status=EvalStatus.FAIL, message="no folder or calendar requirement was comparable", metadata=metadata)
        if failed:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="Thunderbird folder and calendar checks failed: %s" % ", ".join(failed[:8]),
                metadata=metadata,
            )
        return EvalResult(status=EvalStatus.PASS, message=self.PASS_MESSAGE, metadata=metadata)

    @staticmethod
    def _calendar_titles(evidence: Mapping[str, Any]) -> list[str]:
        titles: list[str] = []
        for profile in evidence.get("profiles") or []:
            if not isinstance(profile, Mapping):
                continue
            for event in profile.get("events") or []:
                if isinstance(event, Mapping):
                    titles.append(str(event.get("title") or "").strip())
        return titles


class ThunderbirdTaskEvaluator(BaseEvaluator):
    """Verify the message-filter rules stored in the profile."""

    PASS_MESSAGE = "Thunderbird filter checks passed"
    FAIL_MESSAGE = "Thunderbird filter checks failed"

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = dict(context.get("params") or {})
        contract = params.get("osworld_evaluator")
        timeout = int(params.get("timeout", DEFAULT_TIMEOUT) or DEFAULT_TIMEOUT)
        if not isinstance(contract, Mapping):
            return EvalResult(status=EvalStatus.FAIL, message="the task declares no filter-rule contract")

        declared_path = str(((contract.get("result") or {}) if isinstance(contract.get("result"), Mapping) else {}).get("path") or "").strip()
        expected = contract.get("expected")
        expectations: list[Any] = []
        if isinstance(expected, Mapping):
            rules = expected.get("rules")
            if isinstance(rules, Mapping):
                expectations = list(rules.get("expect") or [])
        if not expectations:
            return EvalResult(status=EvalStatus.FAIL, message="the task declares no expected filter rules")

        paths = self._rule_paths(declared_path, params)
        try:
            observed = _run_program(
                context.get("controller"),
                _RULES_PROGRAM.replace("__PATHS__", repr(paths)),
                timeout,
            )
        except Exception as exc:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="Thunderbird filter rules could not be read: %s: %s" % (type(exc).__name__, exc),
            )

        rules = [dict(rule) for rule in (observed.get("rules") or []) if isinstance(rule, Mapping)]
        checks: list[dict[str, Any]] = []
        for index, expectation in enumerate(expectations, start=1):
            if not isinstance(expectation, Mapping):
                continue
            matches = [rule for rule in rules if self._rule_matches(rule, expectation)]
            label = str(expectation.get("actionValue") or expectation.get("action") or "rule_%d" % index)
            checks.append(
                {
                    "check_id": "filter_rule:%s" % label,
                    "passed": bool(matches),
                    "expected": dict(expectation),
                    "observed": [
                        {
                            "name": rule.get("name"),
                            "enabled": rule.get("enabled"),
                            "action": rule.get("action"),
                            "actionValue": rule.get("actionValue"),
                            "condition": rule.get("condition"),
                            "source": rule.get("__source__"),
                        }
                        for rule in matches[:3]
                    ],
                }
            )

        failed = [check["check_id"] for check in checks if not check["passed"]]
        metadata = {
            "paths": paths,
            "files": observed.get("files"),
            "rules": rules,
            "file_errors": observed.get("errors"),
            "checks": checks,
            "failures": failed,
        }
        if not checks:
            return EvalResult(status=EvalStatus.FAIL, message="no filter rule was comparable", metadata=metadata)
        if failed:
            return EvalResult(
                status=EvalStatus.FAIL,
                message="Thunderbird filter checks failed: %s" % ", ".join(failed[:8]),
                metadata=metadata,
            )
        return EvalResult(status=EvalStatus.PASS, message=self.PASS_MESSAGE, metadata=metadata)

    @staticmethod
    def _rule_paths(declared_path: str, params: Mapping[str, Any]) -> list[str]:
        paths: list[str] = []
        if declared_path:
            paths.append(declared_path)
        profile_dir = str(params.get("profile_dir") or "")
        if not profile_dir and declared_path:
            parents = Path(declared_path).parents
            if len(parents) >= 3:
                profile_dir = str(parents[2])
        if not profile_dir:
            profile_dir = DEFAULT_PROFILE_DIR
        candidate = str(Path(profile_dir) / "Mail" / "Local Folders" / "msgFilterRules.dat")
        if candidate not in paths:
            paths.append(candidate)
        return paths

    @staticmethod
    def _normalize(value: Any) -> str:
        return " ".join(str(value if value is not None else "").split()).strip().casefold()

    @classmethod
    def _rule_matches(cls, rule: Mapping[str, Any], expectation: Mapping[str, Any]) -> bool:
        for key, wanted in expectation.items():
            seen = rule.get(key)
            if isinstance(wanted, (list, tuple)):
                if not any(cls._normalize(seen) == cls._normalize(item) for item in wanted):
                    return False
                continue
            if seen is None:
                return False
            if cls._normalize(seen) != cls._normalize(wanted):
                return False
        return True
